Outputs.HeadOffset:
if (regulateHead)
    return [HeadRegulatorTapping(abs(AveragedMechanical[1]))];

var setpoint := RegulatorZ.MaximalPossibleSetpoint * RegulatorZ.RelativeSetpoint;


/* Adjust output of regulator to be rather too small
than too large
*/
var currentOutput := HeadRegulatorTapping(setpoint);
var speed := 0.2; // arbitrary value, to be optimized - corresponds to adjustment speed

var direction := 0;
if (currentOutput > HeadOffset)
    direction := 1. - speed;
else if (currentOutput < HeadOffset)
    direction := 1. + speed;

//RegulatorZ.MaximalPossibleSetpoint - (1.0 - RegulatorZ.RelativeSetpoint) * 50;

var adjustmentSetpoint := setpoint * direction;
HeadRegulatorTapping(adjustmentSetpoint);


return [adjustHeadOffset(HeadOffset,targetHeadOffset)];

Outputs.Mechanical:
var v[6];

for (var n := 0; n < 6; n += 1) {
    if(n == 5) 
        v[n] := (9000-HeadOffset)*headCalibration; 
    else 
        v[n] := AveragedMechanical[n];
}

return [v];

Arriving.Z:
// check drift only after sleepTime has passed
if (Scan.Time < sleepTime) {
    Scan.Arriving();
    return [];
}
// check every 2 sec
var t := sleepTime;
sleepTime := t + 2000;


targetHeadOffset := 0.0;


// continue Arriving if drift is above threshold
if (abs(previousZDrift - AveragedZ) > maxZDrift) {
    previousZDrift := AveragedZ;
    Scan.Arriving();
} 

return [];

MovingForward.XY:
// generic 2D scan without overscanning

targetHeadOffset := 0.0;

// generic 2D scan without overscanning
var x_s;
var y_s;
if (Scan.Columns == 1)
    x_s := ((PixelColumn)/Scan.Columns-0.5) * Scan.Size.X;
else
    x_s := ((PixelColumn)/(Scan.Columns-1)-0.5) * Scan.Size.X;
if (Scan.Rows == 1)
    y_s := ((PixelRow)/Scan.Rows-0.5) * Scan.Size.Y;
else
    y_s := ((PixelRow)/(Scan.Rows-1)-0.5) * Scan.Size.Y;

// var x := x_s + Scan.Center.X;
// var y := y_s + Scan.Center.Y;
var sina := sin(Scan.Rotation);
var cosa := cos(Scan.Rotation);

var x := Scan.Center.X - sina * y_s + cosa * x_s;
var y := Scan.Center.Y + sina * x_s + cosa * y_s;

if (abs(UnaveragedX-x)<0.01 and abs(UnaveragedY-y)< 0.01 and abs(HeadOffset-targetHeadOffset)<10.0)
    Scan.WaitingForward();

return [x,y];

WaitingForward.RowColumnDepth:
/*
Resetting HeadRegulator to start the initial output at max.
extention during next MovingForward. This is done by providing 
a value much larger than the designated setpoint. This moves 
the regulator to its max value while it does not affect anything.
*/
//HeadRegulatorTapping(100. * runtimeSetpoint);
if (not (waitForSpectrum)){
    waitForSpectrum := true;
    Scan.SuspendToWaitForClient();
    return [];
}
if (not (Scan.IsSuspendedToWaitForClient))
    Scan.MovingBackward();
    return [PixelRow,PixelColumn,0];
return [];

MovingBackward.Z:
regulateHead := false;
waitForSpectrum := false;
targetHeadOffset := -9700.0;
if (abs(HeadOffset - targetHeadOffset) < 10.0)
    Scan.WaitingBackward();
return [UnaveragedZ];

WaitingBackward.RowColumnDepth:
if (not (waitForSpectrum)){
    waitForSpectrum := true;
    Scan.SuspendToWaitForClient();
    return [];
}
if (not (Scan.IsSuspendedToWaitForClient))
    Scan.MovingNextRow();
    return [PixelRow,PixelColumn,1];
return [];

MovingNextRow.Z:
/*regulateHead := true;
if ((abs(AveragedMechanical[1])<runtimeSetpoint) or (HeadOffset <= -9700.0)){
    regulateHead := false;
    return [];
}*/

return [UnaveragedZ];

MovingNextRow.RowColumnDepth:
var row := PixelRow;
var col := PixelColumn + 1;
if (col == Scan.Columns) {
    col := 0;
    row += 1;
}
var setpoint := RegulatorZ.MaximalPossibleSetpoint * (RegulatorZ.RelativeSetpoint+0.03);
if (abs(AveragedMechanical[1]) > setpoint){
    targetHeadOffset := targetHeadOffset + 8;
    regulateHead := false;
    return [];
}
else
    regulateHead := true;

if (Scan.Time < 600)
    return [];

if (row == Scan.Rows)
    Scan.End();
else
    Scan.MovingForward();
return [row, col, 0];

Departing.Z:
regulateHead := false;
targetHeadOffset := 0.0;
if (abs(HeadOffset) > 5)
    Scan.Departing();
return [];
